import scala.concurrent.{Future, ExecutionContext}
import scala.concurrent.duration._
import scala.util.{Try, Success}

// Scala's async composition is Future chaining on an ExecutionContext trampoline:
// a flatMap chain does not grow the stack because the ExecutionContext's
// trampoline executes continuations in a loop, not by nesting.
implicit val ec: ExecutionContext = ExecutionContext.global

def handle(id: String): Future[Result] = for {
  user   <- fetchUser(id)                 // each step returns a Future; no colour propagates
  orders <- fetchOrders(user)
} yield Result(user, orders)

// recover/transform compose failure and success without exceptions:
handle(id).recover { case NonFatal(e) => Result.fallback }

// timeout and cancellation are composition, not interrupts:
handle(id).timeout(2.seconds)
